import numpy as np
from scipy import stats

MAX_DRIVERS = 4

def design(feats):
    # Identify potential drivers (clinical or cohort variables)
    clinical_vars = [fid for fid, typ in zip(feats.ids, feats.types) if typ == 'clinical']

    # If we have clinical variables, check if any drives outcome strongly
    if clinical_vars:
        # Check correlation between clinical variables and outcome
        best_clinical = None
        max_corr = 0
        for fid in clinical_vars:
            col_idx = feats.column(fid)
            corr = np.corrcoef(feats.x[:, col_idx], feats.y)[0, 1]
            if abs(corr) > max_corr:
                max_corr = abs(corr)
                best_clinical = fid

        # If strong correlation, use as driver
        if max_corr > 0.2:
            return Design(
                drivers=(best_clinical,),
                columns=feats.ids,
                products=(),
                loadings={}
            )

    # No clear driver found, look for strong individual predictors
    # Use Welch's t-test to rank features
    scores = []
    for i, fid in enumerate(feats.ids):
        feat_vals = feats.x[:, i]
        y0 = feat_vals[feats.y == 0]
        y1 = feat_vals[feats.y == 1]

        # Welch's t-test
        if len(y0) > 1 and len(y1) > 1:
            t_stat, _ = stats.ttest_ind(y0, y1, equal_var=False)
        else:
            t_stat = 0

        scores.append(abs(t_stat))

    # Rank features by score
    ranked_indices = np.argsort(scores)[::-1]
    drivers = []
    for i in ranked_indices:
        if len(drivers) >= MAX_DRIVERS:
            break
        if scores[i] > 1.0:
            drivers.append(feats.ids[i])

    drivers = tuple(drivers)

    # If no strong drivers, return empty design
    if not drivers:
        return Design(
            drivers=(),
            columns=feats.ids,
            products=(),
            loadings={}
        )

    # For the design, include all features and add some products of top features
    columns = feats.ids
    products = []

    # Add products of top features (if more than one driver)
    if len(drivers) > 1:
        top_drivers = list(drivers)[:3]  # Top 3 drivers
        for i in range(len(top_drivers)):
            for j in range(i+1, len(top_drivers)):
                products.append((top_drivers[i], top_drivers[j]))

    # Create weighted loading based on t-scores
    loadings = {}
    for i, fid in enumerate(feats.ids):
        feat_vals = feats.x[:, i]
        y0 = feat_vals[feats.y == 0]
        y1 = feat_vals[feats.y == 1]
        if len(y0) > 1 and len(y1) > 1:
            t_stat, _ = stats.ttest_ind(y0, y1, equal_var=False)
            loadings[fid] = t_stat

    return Design(
        drivers=drivers,
        columns=columns,
        products=tuple(products),
        loadings=loadings
    )
